sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float angle;
uniform float stretch;
uniform float offset;
uniform float spread;
uniform float relative;
half4 main(float2 coord) {
    float r = radians(angle);
    float2 dir = float2(cos(r), sin(r));
    float unit = relative > 0.5 ? (abs(size.x * dir.x) + abs(size.y * dir.y)) * 0.001 : 1.0;
    float d = dot(coord - 0.5 * size, dir) - offset * unit;
    float gap = 0.5 * max(stretch, 0.0) * unit;
    float2 from = abs(d) <= gap ? coord - dir * d + dir * (d / max(gap, 0.001)) * spread : coord - dir * sign(d) * gap;
    return image.eval(from);
}
